var t=[{title:`Trainen in de hitte`,text:`Hitte en vochtigheid kunnen een makkelijke training veel zwaarder laten voelen. Kies koelere uren en schaduwrijke routes, begin rustig en drink genoeg voor de omstandigheden. De CDC adviseert te stoppen en naar een koele plek te gaan als je je duizelig of zwak voelt. Verwardheid, instorten of een vermoedelijke hitteberoerte vraagt om spoedhulp.`},{title:`Koude, natte en winderige dagen`,text:`Draag lagen die je kunt uitdoen en bedek blootgestelde huid als het koud is. Regen en zweet kunnen kleding en oppervlakken gevaarlijk koud maken, en strenge kou kan bevriezing of onderkoeling veroorzaken. IJs of slecht zicht is een goede reden om die dag binnen te trainen.`},{title:`Controleer de ondergrond`,text:`Let op gaten, los grind, wortels, ongelijke bestrating, slechte verlichting en oversteekplaatsen. Hellingen veranderen de belasting van je spieren en gewrichten. Begin op een nieuwe route in een comfortabel tempo, sla sprints op volle snelheid over en draag schoenen met goede grip voor de ondergrond.`},{title:`Controleer de apparatuur in het park`,text:`Banken, leuningen en optrekstangen kunnen verweerd of los zijn, of niet gebouwd voor dynamische oefeningen. Let op scherpe randen, roest, kapotte verbindingen en wiebelende steunen. Hang nergens aan tenzij het duidelijk gebouwd is om je te dragen. Geef fietsers, kinderen en andere parkgebruikers ruim de ruimte.`},{title:`Controleer elke keer opnieuw`,text:`Buitenomstandigheden veranderen, dus kijk elke keer opnieuw als je naar buiten gaat. Schakel bij gevaarlijk weer over op een training binnen of met lage impact en kies routes en bewegingen die passen bij het licht, de ondergrond en je ervaring.`}];var i=[{label:`CDC: sporten bij hitte`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`},{label:`CDC: bevriezing en onderkoeling voorkomen`,url:`https://www.cdc.gov/winter-weather/prevention/preventing-frostbite.html`},{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};